    'vatCodes.intro': 'Chaque écriture porte un code TVA de la liste de Banana Comptabilité. Le code indique dans quels chiffres du décompte TVA le montant entre et si le montant contient l’impôt. Les chiffres affichés ici viennent du même calcul que le décompte.',
